content:
I'll create the two new log files for dev and prod environments, each declaring a logs bucket and a scoped reader identity.

`src/envs/dev/infra/logs.ts`
```typescript
import {
  ReaderIam,
  SecureBucket,
} from "../../../composites/index.js";

const ENV = "dev";
const REGION = "us-east-1";

export const logs = SecureBucket({
  name: "myapp-logs-dev",
  env: ENV,
  region: REGION,
});

export const logsReader = ReaderIam({
  name: "myapp-dev-logs",
  env: ENV,
  bucketName: "myapp-logs-dev",
  trust: { mode: "account", accountID: "123456789012" },
  additionalActions: ["s3:PutObject"],
  programmaticAccess: true,
});
```

`src/envs/prod/infra/logs.ts`
```typescript
import {
  ReaderIam,
  SecureBucket,
} from "../../../composites/index.js";

const ENV = "prod";
const REGION = "us-east-1";
const APP_NAMESPACE = "app";
const SERVICE_ACCOUNT = "myapp";

export const logs = SecureBucket({
  name: "myapp-logs-prod",
  env: ENV,
  region: REGION,
});

export const logsReader = ReaderIam({
  name: "myapp-prod-logs",
  env: ENV,
  bucketName: "myapp-logs-prod",
  trust: {
    mode: "oidc",
    providerARN: "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    issuerHost: "oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEPROD",
    serviceAccountNamespace: APP_NAMESPACE,
    serviceAccountName: SERVICE_ACCOUNT,
  },
  additionalActions: ["s3:PutObject"],
  programmaticAccess: false,
  podIdentity: {
    clusterName: "myapp-prod",
    serviceAccountNamespace: APP_NAMESPACE,
    serviceAccountName: SERVICE_ACCOUNT,
  },
});
```

Each file creates a logs bucket with `SecureBucket` (inheriting the posture: versioning, AES-256 encryption, no public access) and a reader identity that grants `s3:GetObject` (baseline) plus `s3:PutObject` (via `additionalActions`), scoped only to that environment's logs bucket. The trust relationships match each environment's existing reader pattern: account-based in dev with an IAM user, OIDC+pod identity in prod.
